ALTER TABLE stock_transfers ADD FOREIGN KEY(tenant_id,business_id,destination_id) REFERENCES branches(tenant_id,business_id,id);
ALTER TABLE stock_transfer_lines ADD FOREIGN KEY(tenant_id,business_id,branch_id,transfer_id) REFERENCES stock_transfers(tenant_id,business_id,branch_id,id);
ALTER TABLE stock_transfer_lines ADD FOREIGN KEY(tenant_id,business_id,product_id) REFERENCES products(tenant_id,business_id,id);
ALTER TABLE stock_count_lines ADD FOREIGN KEY(tenant_id,business_id,branch_id,count_id) REFERENCES stock_counts(tenant_id,business_id,branch_id,id);
ALTER TABLE stock_count_lines ADD FOREIGN KEY(tenant_id,business_id,product_id) REFERENCES products(tenant_id,business_id,id);
ALTER TABLE purchase_orders ADD CHECK(status IN ('draft','ordered','partially_received','received','cancelled') AND total>0 AND (expected_date IS NULL OR expected_date>=order_date));
ALTER TABLE purchase_lines ADD CHECK(quantity>0 AND received>=0 AND received<=quantity AND unit_cost>0 AND total=round(quantity*unit_cost));
ALTER TABLE goods_receipts ADD CHECK(total>0);
ALTER TABLE goods_receipt_lines ADD CHECK(quantity>0 AND value>=0);
ALTER TABLE supplier_bills ADD CHECK(total>0 AND paid>=0 AND paid<=total AND due_date>=bill_date);
ALTER TABLE expenses ADD CHECK(amount>0 AND status IN ('posted','reversed') AND account IN ('1000 Cash','1010 Bank'));
ALTER TABLE invoices ADD CHECK(total>0 AND paid>=0 AND paid<=total AND due_date>=invoice_date AND status IN ('draft','issued','void'));
ALTER TABLE invoice_lines ADD CHECK(quantity>0 AND unit_price>=0 AND total=round(quantity*unit_price) AND cost>=0);
ALTER TABLE finance_payments ADD CHECK(amount>0 AND ((bill_id IS NOT NULL)::int+(invoice_id IS NOT NULL)::int)=1 AND account IN ('1000 Cash','1010 Bank'));
ALTER TABLE stock_transfers ADD CHECK(branch_id<>destination_id AND status IN ('draft','sent','received','cancelled'));
ALTER TABLE stock_transfer_lines ADD CHECK(quantity>0 AND value>=0);
ALTER TABLE stock_counts ADD CHECK(status IN ('draft','finalized'));
ALTER TABLE stock_count_lines ADD CHECK(expected>=0 AND counted>=0 AND unit_cost>=0);
